// Generate India presentation using pptxgenjs
const pptxgen = require('pptxgenjs');
const fs = require('fs');

let pres = new pptxgen();

// Set layout
pres.layout = pptxgen.LAYOUT_16x9;

// Define theme colors (India-inspired: saffron, white, green, navy)
pres.defineTheme({
  name: 'IndiaTheme',
  colors: {
    'dark': '1E2761', // navy for title
    'light': 'FFFFFF', // white
    'accent': 'FF9933', // saffron
    'secondary': '138808', // green
    'background': 'F5F5DC' // beige? maybe white
  }
});
pres.theme = pres.themeObj['IndiaTheme'];

// Set background
pres.background = { color: 'FFFFFF' }; // white background

// Helper to add title slide
function addTitleSlide() {
  let slide = pres.addSlide();
  slide.addText('India: Culture, History, Economy, Geography', {
    x: 0.5, y: 1.0, w: 9, h: 1.5,
    fontSize: 36, color: '1E2761', bold: true, align: 'center'
  });
  slide.addText('An Interactive Overview', {
    x: 0.5, y: 2.5, w: 9, h: 0.5,
    fontSize: 24, color: '555555', align: 'center'
  });
  // Add navigation icons as shapes with hyperlinks
  // We'll add rectangles that act as buttons
  let btnW = 1.5, btnH = 0.5, startX = 0.5, startY = 4.0;
  const sections = [
    {label: 'Culture', target: 2}, // slide index (0-based)
    {label: 'History', target: 3},
    {label: 'Economy', target: 4},
    {label: 'Geography', target: 5}
  ];
  sections.forEach((sec, i) => {
    let slideObj = pres.addSlide(); // placeholder, will replace? Actually we need to add slides later.
    // Better approach: we will add slides first, then add action buttons linking to slide numbers.
    // We'll add buttons on title slide that link to slide numbers via hyperlink.
    // pptxgenjs supports hyperlinks on shapes via options.href? Let's check.
    // According to pptxgenjs docs, you can add hyperlink to text or shape using `hyperlink` option.
    // We'll add a rectangle shape with hyperlink to slide.
    slide.addShape(pptxgen.shapes.RECTANGLE, {
      x: startX + i*(btnW+0.2), y: startY, w: btnW, h: btnH,
      fill: { color: 'FF9933' },
      line: { color: 'FF9933' },
      text: sec.label,
      fontSize: 18,
      color: 'FFFFFF',
      align: 'center',
      valign: 'middle',
      // hyperlink to slide: need to specify slide index? Use `slide` option?
      // According to docs, hyperlink can be { slide: n } where n is slide number (1-based).
      hyperlink: { slide: sec.target + 1 } // slide numbers start at 1
    });
  });
}

// Add content slide function
function addContentSlide(title, contentRows) {
  let slide = pres.addSlide();
  slide.addText(title, {
    x: 0.5, y: 0.5, w: 9, h: 0.5,
    fontSize: 28, color: '1E2761', bold: true
  });
  // Content as two columns: left text, right image placeholder
  let leftX = 0.5, leftY = 1.2, leftW = 4.5, leftH = 4.0;
  let rightX = 5.2, rightY = 1.2, rightW = 4.0, rightH = 4.0;
  // Add text boxes for each row
  contentRows.forEach((row, idx) => {
    slide.addText(row.text, {
      x: leftX, y: leftY + idx*0.6, w: leftW, h: 0.5,
      fontSize: 18, color: '333333'
    });
  });
  // Add placeholder shape for image/icon on right
  slide.addShape(pptxgen.shapes.RECTANGLE, {
    x: rightX, y: rightY, w: rightW, h: rightH,
    fill: { color: 'E0E0E0' },
    line: { color: 'B0B0B0' },
    text: 'Image/Icon',
    fontSize: 16,
    color: '666666',
    align: 'center',
    valign: 'middle'
  });
}

// Add slides
addTitleSlide();

// Define content for each section
const cultureContent = [
  {text: 'Languages: 22 officially recognized languages, hundreds of dialects.'},
  {text: 'Religions: Hinduism, Islam, Christianity, Sikhism, Buddhism, Jainism.'},
  {text: 'Festivals: Diwali, Holi, Eid, Christmas, Navratri, Durga Puja.'},
  {text: 'Cuisine: Diverse regional cuisines, spices, vegetarian traditions.'},
  {text: 'Arts: Classical dance (Bharatanatyam, Kathak), music, cinema (Bollywood).'}
];

const historyContent = [
  {text: 'Ancient Civilization: Indus Valley Civilization (c. 3300–1300 BCE).'},
  {text: 'Vedic Period & Empires: Maurya, Gupta, Mughal empires.'},
  {text: 'Colonial Era: British rule (1858–1947), independence movement.'},
  {text: 'Independence: 1947, partition, Republic declared 1950.'},
  {text: 'Modern India: Economic growth, technological advancement, global influence.'}
];

const economyContent = [
  {text: '5th largest economy by nominal GDP, 3rd by PPP.'},
  {text: 'Key sectors: Information technology, agriculture, manufacturing, services.'},
  {text: 'Major industries: Textiles, pharmaceuticals, automobiles, telecommunications.'},
  {text: 'Trade: Major exports include petroleum products, gems, machinery, chemicals.'},
  {text: 'Growth: Rapid urbanization, rising middle class, startup ecosystem.'}
];

const geographyContent = [
  {text: 'Location: South Asia, bordered by Pakistan, China, Nepal, Bhutan, Bangladesh, Myanmar.'},
  {text: 'Landscape: Himalayas, Indo-Gangetic plain, Thar Desert, Deccan Plateau, coastal regions.'},
  {text: 'Rivers: Ganges, Brahmaputra, Indus, Yamuna, Godavari, Krishna.'},
  {text: 'Climate: Tropical monsoon, diverse alpine to desert climates.'},
  {text: 'Biodiversity: Rich flora and fauna, numerous national parks and wildlife sanctuaries.'}
];

addContentSlide('Culture', cultureContent);
addContentSlide('History', historyContent);
addContentSlide('Economy', economyContent);
addContentSlide('Geography', geographyContent);

// Add conclusion slide
let conclSlide = pres.addSlide();
conclSlide.addText('Thank You!', {
  x: 0.5, y: 1.5, w: 9, h: 1.0,
  fontSize: 36, color: '1E2761', bold: true, align: 'center'
});
conclSlide.addText('Explore the Incredible India', {
  x: 0.5, y: 2.8, w: 9, h: 0.5,
  fontSize: 24, color: '555555', align: 'center
});

// Write file
const outPath = 'C:/Users/achal/Desktop/India_Presentation.pptx';
pres.writeFile({ fileName: outPath });
console.log(`Presentation written to ${outPath}`);

